import{_ as i,H as t,f as n,i as a}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"24 | “魔改”的Android系统：厂商定制的Android系统为什么也要解耦？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Android 系统架构","slug":"android-系统架构","link":"#android-系统架构","children":[]},{"level":2,"title":"对 Anroid 系统的“魔改”","slug":"对-anroid-系统的-魔改","link":"#对-anroid-系统的-魔改","children":[{"level":3,"title":"场景 1：应用之间的耦合","slug":"场景-1-应用之间的耦合","link":"#场景-1-应用之间的耦合","children":[]},{"level":3,"title":"场景 2：应用与框架之间的耦合","slug":"场景-2-应用与框架之间的耦合","link":"#场景-2-应用与框架之间的耦合","children":[]},{"level":3,"title":"场景 3：框架之间的耦合","slug":"场景-3-框架之间的耦合","link":"#场景-3-框架之间的耦合","children":[]}]},{"level":2,"title":"耦合带来的问题","slug":"耦合带来的问题","link":"#耦合带来的问题","children":[{"level":3,"title":"问题 1：大量重复的代码合并工作","slug":"问题-1-大量重复的代码合并工作","link":"#问题-1-大量重复的代码合并工作","children":[]},{"level":3,"title":"问题 2：并行维护多个版本","slug":"问题-2-并行维护多个版本","link":"#问题-2-并行维护多个版本","children":[]},{"level":3,"title":"问题 3：“未知”的产品质量","slug":"问题-3-未知-的产品质量","link":"#问题-3-未知-的产品质量","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大型Android系统重构实战/24｜“魔改”的Android系统：厂商定制的Android系统为什么也要解耦？.md","filePath":"大型Android系统重构实战/24｜“魔改”的Android系统：厂商定制的Android系统为什么也要解耦？.md","lastUpdated":1795555367000}'),r={name:"大型Android系统重构实战/24｜“魔改”的Android系统：厂商定制的Android系统为什么也要解耦？.md"};function o(d,e,s,E,l,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_24-魔改-的android系统-厂商定制的android系统为什么也要解耦" tabindex="-1">24 | “魔改”的Android系统：厂商定制的Android系统为什么也要解耦？ <a class="header-anchor" href="#_24-魔改-的android系统-厂商定制的android系统为什么也要解耦" aria-label="Permalink to &quot;24 | “魔改”的Android系统：厂商定制的Android系统为什么也要解耦？&quot;">​</a></h1><p>你好，我是黄俊彬。</p><p>上节课，我们了解了 Android 系统开发的基础框架、编译环境、开发工具等基础知识。这节课，让我们聚焦在架构设计层面，看看定制系统里最容易出现哪些架构耦合问题，这些问题又会给整机产品埋下哪些隐患。</p><p>想要分析架构层面的耦合问题，自然要先弄清楚规范的 Android 系统架构长什么样，就让我们从这里开始今天的内容吧！</p><h2 id="android-系统架构" tabindex="-1">Android 系统架构 <a class="header-anchor" href="#android-系统架构" aria-label="Permalink to &quot;Android 系统架构&quot;">​</a></h2><p>做过 Android 系统定制开发的同学，一定会接触到 AOSP。AOSP，全称是 Android OpenSource Project，中文译为“Android 开放源代码项目”。厂商每年会基于 Google 开放的最新代码进行适配定制，开发属于自己的 OS 版本。</p><p>首先，我们根据 Android 的架构图来看看 Android 系统架构的设计。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/1.png" alt=""></a></p><ul><li>图片来自Google官网介绍 <a href="https://source.android.com/docs/core/architecture" target="_blank" rel="noreferrer">https://source.android.com/docs/core/architecture</a></li></ul><p>对照架构图，我们从上到下来看。在应用框架层上面应该还有一层，就是诸多的应用。</p><p>这些应用可以分为 2 类：一类是系统应用，拥有高的系统权限，可以调用系统提供的高权限接口，例如打电话、短信、设置等应用；另外一类就是非系统应用，与第三方应用一样，例如定制一些便签、运动健康、视频播放等应用。</p><p>接下来的第一层就是应用框架层，应用框架最常被应用开发者使用，对应用提供标准的 API来调用系统的能力，从而实现相关的业务功能。我们在代码编译时，通常会依赖 Android SDK的 android.jar 空包，保证能通过编译。但需要注意的是 android.jar 具体的实现都在框架层中，实际运行时调用的都是系统中的类。</p><p>第二层是 Binder IPC。有了 Binder 进程间通信 (IPC) 机制，应用框架就能跨越进程边界并调用 Android 系统服务代码。由于系统的很多服务都是运行在 System Server 进程，但是集成到应用的 SDK 代码是运行在应用的进程，所以需要通过 Binder 的方式来实现跨进程间的通信。</p><p>第三层是系统服务层。系统服务专注于特定功能的模块化组件，例如窗口管理器、搜索服务或通知管理器。例如我们熟悉的 AMS、WMS、PMS 等，都运行在系统服务层。</p><p>第四层是硬件抽象层 (HAL)。Google 在 Android 8.0 里一个名为“Treble”的项目中设计了 HAL层，目的是让制造商能够以更低成本、更轻松快速地将设备更新到新版 Android 系统。在这种新架构中，HAL 接口定义语言指定了 HAL 和其用户之间的接口，让用户无需重新构建HAL，就能替换 Android 框架。</p><p>最后一层是 Linux 内核层。Google 在官网介绍的开发 Android 设备驱动程序与开发典型的Linux 设备驱动程序类似。但 Android 使用的 Linux 内核版本包含一些特殊的补充功能，例如低内存终止守护进程、唤醒锁定、Binder IPC 驱动程序等，对于移动嵌入式平台，这些是非常重要的功能。</p><h2 id="对-anroid-系统的-魔改" tabindex="-1">对 Anroid 系统的“魔改” <a class="header-anchor" href="#对-anroid-系统的-魔改" aria-label="Permalink to &quot;对 Anroid 系统的“魔改”&quot;">​</a></h2><p>既然 Android 系统已经有了规范的架构设计，为什么定制 Android 系统还会产生耦合的问题呢？</p><p>由于手机产品涉及软硬结合，所以一般会采用 IPD 产品开发流程，研发一款手机的时间通常需要 3 - 12 个月的时间，并按照每款手机项目单独立项跟踪。迫于交付压力，再加上缺少有效的架构设计及守护等问题，开发人员会对系统做各种各样“花式的魔改”，最典型的是后面这3 种耦合场景。</p><h3 id="场景-1-应用之间的耦合" tabindex="-1">场景 1：应用之间的耦合 <a class="header-anchor" href="#场景-1-应用之间的耦合" aria-label="Permalink to &quot;场景 1：应用之间的耦合&quot;">​</a></h3><p>理论上来说，应用之间都是相对独立的。但是在定制系统中，有一些应用在运行时存在相互依赖，例如桌面与负一屏（基于桌面向右滑动后的快捷入口）。这里应用 A 在运行时可能需要调用应用 B 提供的某些方法，才能保证功能正常运行，如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/2.png" alt=""></a></p><p>这里看起来似乎合理，编译上没有依赖，运行时也是通过标准的 API 调用。但关键的问题是不同项目上的功能有差异，依赖的 API 会有变化，并且应用之间并没有做好兼容性的处理，这样导致应用 B 不存在时，应用 A 无法正常运行。你可以结合下图来理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/3.png" alt=""></a></p><h3 id="场景-2-应用与框架之间的耦合" tabindex="-1">场景 2：应用与框架之间的耦合 <a class="header-anchor" href="#场景-2-应用与框架之间的耦合" aria-label="Permalink to &quot;场景 2：应用与框架之间的耦合&quot;">​</a></h3><p>接下来，我们来看第二种典型的耦合场景，应用与框架之间的耦合。</p><p>做过应用开发的同学应该知道，我们需要依赖 Android 的 SDK 来开发。因为 Google 会保持SDK 接口的稳定及兼容，所以基于标准 SDK 开发的应用，才能运行在各个大版本的 Android系统中。</p><p>但是在框架里面还有一些类被标识了 @hide，或者有些类属于 com.android.internal 中的类，这些都是标准的 SDK 不会提供的。</p><p>但是，厂商可以编译生成完整的 android.jar 包，这样应用就可以调用到这些非公开的接口，以便实现更加丰富的功能。当然还有一些应用采用另外一种方法，就是使用反射的形式。你可以结合后面的示意图来理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/4.png" alt=""></a></p><p>由于这部分 API，Google 在大版本的迭代中并不一定保证兼容，所以这也意味着一旦使用这个特殊的 Jar 包的应用，就与特定的大版本绑定了。应用需要针对每一个大版本都维护一个特定的 APK。</p><p>我还遇到过一种更“反直觉”的操作——框架依赖应用。比如在框架层增加代码，会去调用 APP中相关的资源及代码。这种反向的耦合更容易出现问题，因为一旦底层框架代码的兼容性没有处理好，就很容易导致无法开机、黑屏等严重后果。</p><h3 id="场景-3-框架之间的耦合" tabindex="-1">场景 3：框架之间的耦合 <a class="header-anchor" href="#场景-3-框架之间的耦合" aria-label="Permalink to &quot;场景 3：框架之间的耦合&quot;">​</a></h3><p>第三种典型的耦合场景是框架之间的耦合，这里的框架耦合指的是厂商扩展的代码与框架之间的耦合。</p><p>为了扩展系统的功能，定制 Android 系统可以在框架中添加一些代码，例如可以在 AMS 里面的 Activity 生命周期回调增加一些统计代码，就能统计到应用界面的一些执行情况。这些能力是三方应用无法实现的功能，是厂商定制应用的优势。你可以参考后面的示意图来理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/5.png" alt=""></a></p><p>但是缺少规范化的管理及灵活的插桩设计，也会产生耦合问题。我们都知道 Google 每年都会更新 AOSP 基线代码，框架之间的耦合会导致扩展的代码与框架代码强关联。一方面这些代码只能跟随着框架代码一起维护，无法做到独立维护；另外一方面当代码有更新时，维护成本也非常高。</p><h2 id="耦合带来的问题" tabindex="-1">耦合带来的问题 <a class="header-anchor" href="#耦合带来的问题" aria-label="Permalink to &quot;耦合带来的问题&quot;">​</a></h2><p>除了前面提到的定制 Android 系统的耦合问题，耦合也会影响到团队效率以及产品质量，接下来我们就重点探讨三个常见问题。</p><h3 id="问题-1-大量重复的代码合并工作" tabindex="-1">问题 1：大量重复的代码合并工作 <a class="header-anchor" href="#问题-1-大量重复的代码合并工作" aria-label="Permalink to &quot;问题 1：大量重复的代码合并工作&quot;">​</a></h3><p>前面提到 Google 每年都会升级一个 Android 的大版本，对于厂商来说，他们其实拿到的是第三手代码。前面还有一个上游——芯片平台。为了帮助你理解，我画了后面这张示意图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/6.png" alt=""></a></p><p>因为是第三手代码，为了保证本地代码能及时同步上游的最新代码，厂商需要定期去同步上游的代码，大版本可能是每年一次，补丁 Patch 可能是 2 周一次。由于侵入性的修改，容易导致代码冲突的出现，特别是每次的大版本更新。</p><p>另外，由于各种耦合的问题，通常最后量产版本时需要拉去独立的 MP 分支。这样，并行的项目越多时，合并代码的工作量就会呈指数级爆发。</p><h3 id="问题-2-并行维护多个版本" tabindex="-1">问题 2：并行维护多个版本 <a class="header-anchor" href="#问题-2-并行维护多个版本" aria-label="Permalink to &quot;问题 2：并行维护多个版本&quot;">​</a></h3><p>由于应用于架构和耦合问题，会让不同项目集成难度升高。因为应用无法做到一个 apk 适配多个项目，这样对于应用来说往往需要同时维护 3-5 个版本，并且通常也是采用拉取分支的形式，一个分支出一个项目版本的 APK。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/7.png" alt=""></a></p><p>同时，维护多个版本带来了大量重复性的工作。例如当修复一个 Bug 时，需要同步到若干个分支中，并且带给测试同学的压力也非常大。由于每个分支的代码都不是完全一致的，需要做回归测试时，工作量也会翻倍。</p><h3 id="问题-3-未知-的产品质量" tabindex="-1">问题 3：“未知”的产品质量 <a class="header-anchor" href="#问题-3-未知-的产品质量" aria-label="Permalink to &quot;问题 3：“未知”的产品质量&quot;">​</a></h3><p>由于代码的耦合问题，非常容易导致修改代码出现连带问题。所以开发同学会选择尽可能少修改代码，更别谈去做一些中大型的代码重构。在机型数量越来越多的状态下，技术复杂度越来越高。两种压力的共同作用下，代码修改越多，代码重构就变得越来越难，代码质量完全无法把控。</p><p>另外，对于产品的质量也带来了非常大的挑战。前面提到的多项目、多版本的问题，导致在最后集成阶段需要大量的回归测试，然而在缺乏高质量的自动化测试覆盖下，仅靠人工很难进行全面的验证，这样就非常容易导致问题流到线上用户手中。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>今天我们一起了解了 Android 的系统架构，与前面讲过的应用分层架构类似，Android 系统也是采用模块化的分层架构。各个分层职责清晰，从上到下依次为应用框架层、Binder IPC、系统服务层、硬件抽象层以及 Linux 内核层。</p><p>但是当厂商开始定制 Android 系统时，由于项目管理、交付压力等等情况，非常容易出现不按规矩出牌的情况，我总结了 3 种最常见的耦合场景，你可以通过后面的表格回顾。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/24/8.png" alt=""></a></p><p>由于耦合的问题，团队需要完成大量重复、机械性的代码合并工作，也需要同时维护多个并行的版本。开发同学淹没在数不尽的分支合并任务里，测试同学淹没在数不尽的黑盒测试中，团队无法把精力投入到代码优化和更多产品质量优化工作上，时间一久，就会给系统埋下诸多隐患。</p><p>下节课，我们就聊聊应对这些耦合问题的具体思路，敬请期待。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>感谢你学完了今天的内容，今天的思考题是这样的：你觉得 Android 系统的耦合与应用的耦合有哪些相同点和差异点呢？</p><p>欢迎你在留言区与我交流讨论，也欢迎你把它分享给你的同事或朋友，我们一起来高效、高质量交付软件！</p>',60)])])}const c=i(r,[["render",o]]);export{A as __pageData,c as default};
